    Object.keys(catMap).forEach(function (cat) {
      var items = catMap[cat].slice(0, 5);
      html += '<div class="aioq-square-cat-section">' +
        '<div class="aioq-square-cat-head">' +
          '<h3>' + escapeHtml(cat) + '</h3>' +
