  /* ---- Mine tab sections ---- */

  function renderMineTab() {
    var grid = document.getElementById('squareAgentGrid');
    var empty = document.getElementById('squareEmpty');
    if (!grid) return;

    var mineItems = state.items.filter(minePredicate);

    if (!mineItems.length) {
      grid.innerHTML = '';
      if (empty) empty.classList.remove('hidden');
      return;
    }
    if (empty) empty.classList.add('hidden');

    var html = '';

    var recentItems = mineItems.filter(function (item) { return item.lastUsedAt; }).sort(function (a, b) {
      return String(b.lastUsedAt).localeCompare(String(a.lastUsedAt));
    }).slice(0, 8);
    if (recentItems.length) {
      html += '<div class="aioq-square-mine-section">' +
        '<div class="aioq-square-mine-section-head"><h3>最近使用</h3></div>' +
        '<div class="aioq-square-row">' + recentItems.map(function (item) { return cardHtml(item, 'row'); }).join('') + '</div>' +
      '</div>';
    }

    var favItems = mineItems.filter(function (item) { return item.isFavorite; });
    if (favItems.length) {
      html += '<div class="aioq-square-mine-section">' +
        '<div class="aioq-square-mine-section-head"><h3>收藏的智能体</h3></div>' +
        '<div class="aioq-square-row">' + favItems.map(function (item) { return cardHtml(item, 'row'); }).join('') + '</div>' +
      '</div>';
    }

    var personalItems = mineItems.filter(function (item) { return item.groupKey === 'personal' || item.source === 'personal-space'; });
    if (personalItems.length) {
      html += '<div class="aioq-square-mine-section">' +
        '<div class="aioq-square-mine-section-head"><h3>我创建的</h3></div>' +
        '<div class="aioq-square-row">' + personalItems.map(function (item) { return cardHtml(item, 'row'); }).join('') + '</div>' +
