const fs = require('fs');
const path = require('path');
const outDir = path.join(process.cwd(), 'prototype', 'scripts', 'browser-screenshots');
fs.mkdirSync(outDir, { recursive: true });
const nodeModuleDir = 'C:/Users/win/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules';
process.env.NODE_PATH = nodeModuleDir;
require('module').Module._initPaths();
const { chromium } = require('playwright');

const base = 'http://127.0.0.1:8765';
const pages = [
  { name: 'chat', url: `${base}/web%E7%AB%AF/index.html?qa=${Date.now()}` },
  { name: 'square', url: `${base}/web%E7%AB%AF/agent-square.html?qa=${Date.now()}` },
  { name: 'space', url: `${base}/web%E7%AB%AF/my-space.html?qa=${Date.now()}` },
];
const viewports = [
  { name: 'desktop', width: 1440, height: 900 },
  { name: 'mobile', width: 390, height: 844 },
];
const failures = [];
function assert(cond, msg) { if (!cond) failures.push(msg); }
function hasOldText(text) {
  return ['沉淀为智能体', '公开可用', '授权可用', '个人可用', '个人草稿', '历史沉淀'].some(s => text.includes(s));
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  for (const vp of viewports) {
    const context = await browser.newContext({ viewport: { width: vp.width, height: vp.height }, deviceScaleFactor: 1 });
    const pageErrors = [];
    context.on('page', p => {
      p.on('console', msg => { if (['error', 'warning'].includes(msg.type())) pageErrors.push(`${msg.type()}: ${msg.text()}`); });
      p.on('pageerror', err => pageErrors.push(`pageerror: ${err.message}`));
    });
    const page = await context.newPage();
    page.on('console', msg => { if (['error', 'warning'].includes(msg.type())) pageErrors.push(`${msg.type()}: ${msg.text()}`); });
    page.on('pageerror', err => pageErrors.push(`pageerror: ${err.message}`));

    for (const entry of pages) {
      await page.goto(entry.url, { waitUntil: 'networkidle' });
      await page.screenshot({ path: path.join(outDir, `${entry.name}-${vp.name}.png`), fullPage: true });
      const bodyText = await page.locator('body').innerText();
      assert(!hasOldText(bodyText), `${entry.name}/${vp.name}: contains removed wording`);
      assert(await page.locator('#btnModel, #modelMenu').count() === 0, `${entry.name}/${vp.name}: top model selector exists`);
      const overflow = await page.evaluate(() => {
        const vw = document.documentElement.clientWidth;
        const offenders = [];
        document.querySelectorAll('body *').forEach(el => {
          const r = el.getBoundingClientRect();
          const style = getComputedStyle(el);
          if (r.width > 1 && style.display !== 'none' && style.visibility !== 'hidden' && (r.right > vw + 2 || r.left < -2)) {
            offenders.push(`${el.tagName.toLowerCase()}${el.id ? '#'+el.id : ''}${el.className ? '.'+String(el.className).trim().split(/\s+/).slice(0,2).join('.') : ''}:${Math.round(r.left)},${Math.round(r.right)}`);
          }
        });
        return offenders.slice(0, 8);
      });
      assert(overflow.length === 0, `${entry.name}/${vp.name}: horizontal overflow ${overflow.join('; ')}`);
    }

    // Chat flow: history summary note -> my space -> reference note -> send.
    await page.goto(`${base}/web%E7%AB%AF/index.html?qa=flow-${Date.now()}`, { waitUntil: 'networkidle' });
    assert(await page.locator('.aioq-sidebar-block-title:has-text("智能体列表")').count() > 0, 'chat: missing agent list section');
    assert(await page.locator('#btnToggleSidebarHistory').count() > 0, 'chat: missing collapsible history section');
    await page.locator('#chatInput').fill('请先给我一个测试回答');
    await page.locator('#chatSend').click();
    await page.waitForTimeout(900);
    await page.locator('#chatInput').fill('上一轮还不够，请继续补充');
    await page.locator('#chatSend').click();
    await page.waitForTimeout(900);
    await page.locator('#btnHistory').click();
    await page.waitForTimeout(200);
    assert(await page.locator('[data-history-summary]').count() > 0, 'history: missing summary action');
    assert(await page.locator('[data-history-agent]').count() === 0, 'history: found sediment-to-agent action');
    await page.locator('[data-history-summary]').first().click();
    await page.waitForTimeout(200);
    assert(await page.locator('#historySummaryModal:not(.hidden)').count() === 1, 'history: summary modal did not open');
    const roundCount = await page.locator('[data-summary-round]').count();
    assert(roundCount >= 1, `history: expected selectable rounds, got ${roundCount}`);
    const preview = await page.locator('#historySummaryPreview').innerText();
    assert(preview.includes('用户:') && preview.includes('智能体:') && preview.includes('AI总结与评价'), 'history: markdown preview missing required sections');
    await page.locator('#btnSaveHistorySummary').click();
    await page.waitForTimeout(300);
    await page.goto(`${base}/web%E7%AB%AF/my-space.html?qa=note-${Date.now()}`, { waitUntil: 'networkidle' });
    const spaceText = await page.locator('body').innerText();
    assert(spaceText.includes('总结笔记') || spaceText.includes('AI总结与评价'), 'my-space: saved summary note not visible');
    await page.goto(`${base}/web%E7%AB%AF/index.html?qa=note-ref-${Date.now()}`, { waitUntil: 'networkidle' });
    await page.locator('#btnPickNote').click();
    await page.waitForTimeout(200);
    assert(await page.locator('#notePickerModal:not(.hidden)').count() === 1, 'note picker: modal did not open');
    assert(await page.locator('[data-note-pick]').count() > 0, 'note picker: no note selectable');
    await page.locator('[data-note-pick]').first().click();
    await page.waitForTimeout(200);
    assert((await page.locator('#attachChip').innerText()).includes('已引用'), 'note picker: referenced note chip missing');
    await page.locator('#chatInput').fill('结合引用笔记，继续回答这个问题');
    await page.locator('#chatSend').click();
    await page.waitForTimeout(900);
    const answerText = await page.locator('#chatMsgs').innerText();
    assert(answerText.includes('引用了 1 条笔记') || answerText.includes('已引用'), 'chat send: answer did not acknowledge referenced note');

    // Square: 查看全部 switches category and cards stay grid.
    await page.goto(`${base}/web%E7%AB%AF/agent-square.html?qa=square-${Date.now()}`, { waitUntil: 'networkidle' });
    assert(await page.locator('text=智能体广场').count() > 0, 'square: missing title/nav');
    assert(await page.locator('.aioq-square-permission').count() === 0, 'square: permission label visible');
    const beforeCardCount = await page.locator('[data-agent-card]').count();
    assert(beforeCardCount > 0, 'square: no agent cards');
    const viewAll = page.locator('[data-view-category]').first();
    if (await viewAll.count()) {
      await viewAll.click();
      await page.waitForTimeout(300);
      assert(await page.locator('[data-agent-card]').count() > 0, 'square: view all resulted in empty cards');
    }
    const rowOverflow = await page.evaluate(() => {
      const row = document.querySelector('.aioq-square-row');
      if (!row) return false;
      const cs = getComputedStyle(row);
      return cs.overflowX === 'auto' || cs.display === 'flex';
    });
    assert(!rowOverflow, 'square: recommendation row still behaves like horizontal rail');

    // My space: edit links point to ops detail.
    await page.goto(`${base}/web%E7%AB%AF/my-space.html?qa=agent-edit-${Date.now()}`, { waitUntil: 'networkidle' });
    const editLinks = await page.locator('.aioq-space-agent-edit').evaluateAll(nodes => nodes.map(a => a.getAttribute('href')));
    assert(editLinks.length > 0, 'my-space: no agent edit entry');
    assert(editLinks.every(h => h && h.includes('../05-agent-detail.html?id=')), `my-space: bad edit href ${editLinks.join(',')}`);

    await context.close();
    if (pageErrors.length) failures.push(`${vp.name}: console/page errors: ${pageErrors.join(' | ')}`);
  }
  await browser.close();
  if (failures.length) {
    console.error('BROWSER FLOW FAILED');
    failures.forEach(f => console.error('- ' + f));
    process.exit(1);
  }
  console.log('BROWSER FLOW PASSED');
  console.log('screenshots=' + outDir);
})();
