  await page.locator('#chatInput').fill('请先给我一个测试回答');
  await page.locator('#chatSend').click();
  await page.waitForTimeout(900);
  await page.locator('#chatInput').fill('上一轮还不够，请继续补充');
  await page.locator('#chatSend').click();
  await page.waitForTimeout(900);
  await page.locator('#btnHistory').click();
  await page.waitForTimeout(250);
  assert(await page.locator('[data-history-summary]').count() > 0, 'history: missing summary action');
  assert(await page.locator('[data-history-agent]').count() === 0, 'history: has sediment action');
  await page.locator('[data-history-summary]').first().click();
  await page.waitForTimeout(250);
  assert(await page.locator('#historySummaryModal:not(.hidden)').count() === 1, 'history: summary modal closed');
  const roundCount = await page.locator('[data-summary-round]').count();
  assert(roundCount >= 1, `history: no selectable rounds (${roundCount})`);
  const preview = await page.locator('#historySummaryPreview').innerText();
  assert(preview.includes('用户:') && preview.includes('智能体:') && preview.includes('AI总结与评价'), 'history: preview missing markdown sections');
  await page.screenshot({ path: path.join(outDir, 'summary-modal-desktop.png'), fullPage: false });
  await page.locator('#btnSaveHistorySummary').click();
  await page.waitForTimeout(400);

  await page.goto(`${base}/web%E7%AB%AF/my-space.html?qa=space-note-${Date.now()}`, { waitUntil: 'networkidle' });
  const spaceText = await page.locator('body').innerText();
  assert(spaceText.includes('AI总结与评价') || spaceText.includes('总结笔记'), 'my-space: summary markdown not visible');
