{"code":"async (page) => {
  const outDir = 'C:\\Users\\win\\Desktop\\Agent Platform\\prototype\\scripts\\browser-screenshots';
  const base = 'http://127.0.0.1:8765';
  const failures = [];
  const logs = [];
  page.removeAllListeners('console');
  page.removeAllListeners('pageerror');
  page.on('console', msg => { if (['error', 'warning'].includes(msg.type())) logs.push(`${msg.type()}: ${msg.text()}`); });
  page.on('pageerror', err => logs.push(`pageerror: ${err.message}`));
  function assert(cond, msg) { if (!cond) failures.push(msg); }
  function oldText(text) { return ['沉淀为智能体','公开可用','授权可用','个人可用','个人草稿','历史沉淀'].filter(s => text.includes(s)); }
  async function pageCheck(name, url) {
    await page.goto(url, { waitUntil: 'networkidle' });
    const vp = page.viewportSize();
    await page.screenshot({ path: `${outDir}\\${name}-${vp.width}x${vp.height}.png`, fullPage: true });
    const text = await page.locator('body').innerText();
    const removed = oldText(text);
    assert(!removed.length, `${name}: old text ${removed.join(',')}`);
    assert(await page.locator('#btnModel, #modelMenu').count() === 0, `${name}: model selector exists`);
    const overflow = await page.evaluate(() => {
      const vw = document.documentElement.clientWidth;
      const offenders = [];
      document.querySelectorAll('body *').forEach(el => {
        const r = el.getBoundingClientRect();
        const cs = getComputedStyle(el);
        if (r.width > 1 && cs.display !== 'none' && cs.visibility !== 'hidden' && (r.right > vw + 2 || r.left < -2)) {
          offenders.push(`${el.tagName.toLowerCase()}${el.id ? '#'+el.id : ''}${el.className ? '.'+String(el.className).trim().split(/\s+/).slice(0,2).join('.') : ''}:${Math.round(r.left)},${Math.round(r.right)}`);
        }
      });
      return offenders.slice(0, 8);
    });
    assert(overflow.length === 0, `${name}: horizontal overflow ${overflow.join('; ')}`);
  }
  for (const vp of [{w:1440,h:900},{w:390,h:844}]) {
    await page.setViewportSize({ width: vp.w, height: vp.h });
    await pageCheck(`chat-${vp.w}`, `${base}/web%E7%AB%AF/index.html?qa=${Date.now()}`);
    await pageCheck(`square-${vp.w}`, `${base}/web%E7%AB%AF/agent-square.html?qa=${Date.now()}`);
    await pageCheck(`space-${vp.w}`, `${base}/web%E7%AB%AF/my-space.html?qa=${Date.now()}`);
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(`${base}/web%E7%AB%AF/index.html?qa=flow-${Date.now()}`, { waitUntil: 'networkidle' });
  assert(await page.locator('text=智能体列表').count() > 0, 'chat: missing agent list section');
  assert(await page.locator('#btnToggleSidebarHistory').count() > 0, 'chat: missing history collapse button');
  await page.locator('#chatInput').fill('请先给我一个测试回答');
  await page.locator('#chatSend').click();
  await page.waitForTimeout(900);
  await page.locator('#chatInput').fill('上一轮还不够，请继续补充');
  await page.locator('#chatSend').click();
  await page.waitForTimeout(900);
  await page.locator('#btnHistory').click();
  await page.waitForTimeout(250);
  assert(await page.locator('[data-history-summary]').count() > 0, 'history: missing summary action');
  assert(await page.locator('[data-history-agent]').count() === 0, 'history: has sediment action');
  await page.locator('[data-history-summary]').first().click();
  await page.waitForTimeout(250);
  assert(await page.locator('#historySummaryModal:not(.hidden)').count() === 1, 'history: summary modal closed');
  const roundCount = await page.locator('[data-summary-round]').count();
  assert(roundCount >= 1, `history: no selectable rounds (${roundCount})`);
  const preview = await page.locator('#historySummaryPreview').innerText();
  assert(preview.includes('用户:') && preview.includes('智能体:') && preview.includes('AI总结与评价'), 'history: preview missing markdown sections');
  await page.screenshot({ path: `${outDir}\\summary-modal-desktop.png`, fullPage: false });
  await page.locator('#btnSaveHistorySummary').click();
  await page.waitForTimeout(400);
  await page.goto(`${base}/web%E7%AB%AF/my-space.html?qa=space-note-${Date.now()}`, { waitUntil: 'networkidle' });
  const spaceText = await page.locator('body').innerText();
  assert(spaceText.includes('AI总结与评价') || spaceText.includes('总结笔记'), 'my-space: summary markdown not visible');
  const editLinks = await page.locator('.aioq-space-agent-edit').evaluateAll(nodes => nodes.map(a => a.getAttribute('href')));
  assert(editLinks.length > 0, 'my-space: no edit links');
  assert(editLinks.every(h => h && h.includes('../05-agent-detail.html?id=')), `my-space: bad edit hrefs ${editLinks.join(',')}`);
  await page.goto(`${base}/web%E7%AB%AF/index.html?qa=note-ref-${Date.now()}`, { waitUntil: 'networkidle' });
  await page.locator('#btnPickNote').click();
  await page.waitForTimeout(250);
  assert(await page.locator('#notePickerModal:not(.hidden)').count() === 1, 'note picker: modal not open');
  assert(await page.locator('[data-note-pick]').count() > 0, 'note picker: no notes');
  await page.locator('[data-note-pick]').first().click();
  await page.waitForTimeout(250);
  assert((await page.locator('#attachChip').innerText()).includes('已引用'), 'note picker: selected chip missing');
  await page.locator('#chatInput').fill('结合引用笔记，继续回答这个问题');
  await page.locator('#chatSend').click();
  await page.waitForTimeout(900);
  const answerText = await page.locator('#chatMsgs').innerText();
  assert(answerText.includes('引用了 1 条笔记') || answerText.includes('已引用'), 'chat: referenced note not acknowledged');
  await page.goto(`${base}/web%E7%AB%AF/agent-square.html?qa=square-flow-${Date.now()}`, { waitUntil: 'networkidle' });
  assert(await page.locator('.aioq-square-permission').count() === 0, 'square: permission labels visible');
  assert(await page.locator('[data-agent-card]').count() > 0, 'square: no cards');
  if (await page.locator('[data-view-category]').count()) {
    await page.locator('[data-view-category]').first().click();
    await page.waitForTimeout(300);
    assert(await page.locator('[data-agent-card]').count() > 0, 'square: view all empty');
  }
  const rail = await page.evaluate(() => {
    const row = document.querySelector('.aioq-square-row');
    if (!row) return false;
    const cs = getComputedStyle(row);
    return cs.overflowX === 'auto' || cs.display === 'flex';
  });
  assert(!rail, 'square: horizontal rail remains');
  const badLogs = logs.filter(l => !l.includes('favicon'));
  if (badLogs.length) failures.push(`console: ${badLogs.join(' | ')}`);
  return { ok: failures.length === 0, failures, screenshots: outDir };
}"}

